package dev.melix.damagenumbers.client.gui;

import dev.melix.damagenumbers.client.config.CustomFontManager;
import dev.melix.damagenumbers.client.config.DamageNumbersConfig;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

final class DeleteFontScreen extends Screen {
    private static final int PANEL_WIDTH = 320;
    private static final int PANEL_HEIGHT = 118;
    private final DamageNumbersConfigScreen parent;
    private final String fontId;
    private final String fontName;

    DeleteFontScreen(DamageNumbersConfigScreen parent, String fontId, String fontName) {
        super(Component.translatable("damage_numbers.delete_font.title"));
        this.parent = parent;
        this.fontId = fontId;
        this.fontName = fontName;
    }

    @Override
    protected void init() {
        int left = (width - PANEL_WIDTH) / 2;
        int top = (height - PANEL_HEIGHT) / 2;
        int buttonWidth = (PANEL_WIDTH - 46) / 2;
        addRenderableWidget(FlatButton.create(Component.translatable("gui.cancel"), button -> onClose())
                .bounds(left + 20, top + 76, buttonWidth, 22).build());
        addRenderableWidget(FlatButton.create(Component.translatable("damage_numbers.delete_font.confirm"),
                        button -> deleteFont())
                .bounds(left + 26 + buttonWidth, top + 76, buttonWidth, 22).accent().build());
    }

    private void deleteFont() {
        DamageNumbersConfig.get().removeCustomFont(fontId);
        CustomFontManager.deleteFont(minecraft, fontId, () -> minecraft.setScreen(parent));
    }

    @Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float partialTick) {
        graphics.fill(0, 0, width, height, 0xE8000000);
        int left = (width - PANEL_WIDTH) / 2;
        int top = (height - PANEL_HEIGHT) / 2;
        graphics.fill(left, top, left + PANEL_WIDTH, top + PANEL_HEIGHT, 0xFF171A20);
        super.render(graphics, mouseX, mouseY, partialTick);
        drawBorder(graphics, left, top, PANEL_WIDTH, PANEL_HEIGHT, 0xFF58A6FF, 2);
        graphics.drawCenteredString(font, title, width / 2, top + 15, 0xFFF4F6F8);
        graphics.drawCenteredString(font, Component.translatable("damage_numbers.delete_font.description",
                fontName), width / 2, top + 42, 0xFFA6ADB8);
    }

    @Override
    public void onClose() {
        minecraft.setScreen(parent);
    }

    private static void drawBorder(GuiGraphics graphics, int x, int y, int width, int height, int color,
                                   int thickness) {
        graphics.fill(x, y, x + width, y + thickness, color);
        graphics.fill(x, y + height - thickness, x + width, y + height, color);
        graphics.fill(x, y, x + thickness, y + height, color);
        graphics.fill(x + width - thickness, y, x + width, y + height, color);
    }
}

package dev.melix.damagenumbers.client.config;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.fabricmc.loader.api.FabricLoader;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.client.Minecraft;
import net.minecraft.server.packs.repository.PackRepository;
import org.lwjgl.PointerBuffer;
import org.lwjgl.system.MemoryStack;
import org.lwjgl.util.tinyfd.TinyFileDialogs;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.UUID;
import java.util.function.Consumer;

public final class CustomFontManager {
    private static final Logger LOGGER = LoggerFactory.getLogger("damage-numbers/fonts");
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();
    private static final String PACK_FOLDER = "damage-numbers-custom-fonts";
    private static final Path METADATA_PATH = FabricLoader.getInstance().getConfigDir()
            .resolve("damage-numbers-fonts.json");
    private static final Path PACK_PATH = FabricLoader.getInstance().getGameDir()
            .resolve("resourcepacks").resolve(PACK_FOLDER);
    private static boolean startupPackChecked;

    private CustomFontManager() {
    }

    public static void initialize(Minecraft minecraft) {
        if (fonts().isEmpty()) {
            return;
        }
        ClientTickEvents.END_CLIENT_TICK.register(client -> {
            if (!startupPackChecked && client.options != null) {
                startupPackChecked = true;
                enablePack(client, true, null);
            }
        });
    }

    public static synchronized List<CustomFont> fonts() {
        if (!Files.isRegularFile(METADATA_PATH)) {
            return List.of();
        }
        List<CustomFont> fonts = new ArrayList<>();
        try (Reader reader = Files.newBufferedReader(METADATA_PATH, StandardCharsets.UTF_8)) {
            JsonElement root = JsonParser.parseReader(reader);
            JsonArray array = root.isJsonArray() ? root.getAsJsonArray() : new JsonArray();
            for (JsonElement element : array) {
                if (!element.isJsonObject()) {
                    continue;
                }
                JsonObject object = element.getAsJsonObject();
                String id = object.has("id") ? object.get("id").getAsString() : "";
                String name = object.has("name") ? object.get("name").getAsString() : "";
                String extension = object.has("extension") ? object.get("extension").getAsString() : ".ttf";
                if (!id.isBlank() && !name.isBlank()) {
                    fonts.add(new CustomFont(id, name, extension));
                }
            }
        } catch (Exception exception) {
            LOGGER.warn("Could not read custom font metadata", exception);
        }
        return List.copyOf(fonts);
    }

    public static void openImportDialog(Minecraft minecraft, Consumer<CustomFont> onImported) {
        Thread picker = new Thread(() -> {
            String selected;
            try (MemoryStack stack = MemoryStack.stackPush()) {
                PointerBuffer filters = stack.mallocPointer(2);
                filters.put(stack.UTF8("*.ttf"));
                filters.put(stack.UTF8("*.otf"));
                filters.flip();
                selected = TinyFileDialogs.tinyfd_openFileDialog(
                        "Add custom font", "", filters, "TTF / OTF fonts", false);
            }
            if (selected == null) {
                return;
            }
            try {
                CustomFont imported = importFont(Path.of(selected));
                minecraft.execute(() -> enablePack(minecraft, true,
                        () -> onImported.accept(imported)));
            } catch (Exception exception) {
                LOGGER.warn("Could not import custom font {}", selected, exception);
            }
        }, "DamageNumbers font picker");
        picker.setDaemon(true);
        picker.start();
    }

    public static synchronized void deleteFont(Minecraft minecraft, String fontId, Runnable onDeleted) {
        CustomFont font = fonts().stream().filter(candidate -> candidate.id().equals(fontId))
                .findFirst().orElse(null);
        if (font == null) {
            if (onDeleted != null) {
                onDeleted.run();
            }
            return;
        }
        try {
            Files.deleteIfExists(PACK_PATH.resolve("assets/damage-numbers/font/custom")
                    .resolve(font.id() + font.extension()));
            Files.deleteIfExists(PACK_PATH.resolve("assets/damage-numbers/font/custom_" + font.id() + ".json"));
            List<CustomFont> remaining = new ArrayList<>(fonts());
            remaining.removeIf(candidate -> candidate.id().equals(font.id()));
            saveMetadata(remaining);
            enablePack(minecraft, true, onDeleted);
        } catch (IOException exception) {
            LOGGER.warn("Could not delete custom font {}", font.id(), exception);
        }
    }

    private static synchronized CustomFont importFont(Path source) throws IOException {
        if (!Files.isRegularFile(source)) {
            throw new IOException("Font file does not exist: " + source);
        }
        String fileName = source.getFileName().toString();
        int dot = fileName.lastIndexOf('.');
        String extension = dot >= 0 ? fileName.substring(dot).toLowerCase(Locale.ROOT) : "";
        if (!extension.equals(".ttf") && !extension.equals(".otf")) {
            throw new IOException("Only TTF and OTF fonts are supported");
        }
        byte[] header;
        try (var input = Files.newInputStream(source)) {
            header = input.readNBytes(4);
        }
        if (header.length < 4 || header[0] == 'O' && header[1] == 'T'
                && header[2] == 'T' && header[3] == 'O') {
            throw new IOException("CFF-based OpenType fonts are not supported by Minecraft");
        }
        String displayName = dot > 0 ? fileName.substring(0, dot) : fileName;
        String slug = displayName.toLowerCase(Locale.ROOT)
                .replaceAll("[^a-z0-9]+", "_").replaceAll("^_+|_+$", "");
        if (slug.isEmpty()) {
            slug = "font";
        }
        if (slug.length() > 24) {
            slug = slug.substring(0, 24);
        }
        String id = slug + "_" + UUID.randomUUID().toString().substring(0, 8);
        CustomFont font = new CustomFont(id, displayName, extension);

        ensurePackStructure();
        Path fontDirectory = PACK_PATH.resolve("assets/damage-numbers/font/custom");
        Files.createDirectories(fontDirectory);
        Files.copy(source, fontDirectory.resolve(id + extension), StandardCopyOption.REPLACE_EXISTING);
        String definition = """
                {
                  "providers": [
                    {
                      "type": "ttf",
                      "file": "damage-numbers:custom/%s%s",
                      "shift": [0.0, 1.0],
                      "size": 11.0,
                      "oversample": 16.0
                    }
                  ]
                }
                """.formatted(id, extension);
        Files.writeString(PACK_PATH.resolve("assets/damage-numbers/font/custom_" + id + ".json"),
                definition, StandardCharsets.UTF_8);

        List<CustomFont> fonts = new ArrayList<>(fonts());
        fonts.add(font);
        saveMetadata(fonts);
        return font;
    }

    private static void ensurePackStructure() throws IOException {
        Files.createDirectories(PACK_PATH.resolve("assets/damage-numbers/font"));
        String metadata = """
                {
                  "pack": {
                    "pack_format": 15,
                    "supported_formats": {
                      "min_inclusive": 15,
                      "max_inclusive": 999
                    },
                    "description": "DamageNumbers custom fonts"
                  }
                }
                """;
        Files.writeString(PACK_PATH.resolve("pack.mcmeta"), metadata, StandardCharsets.UTF_8);
    }

    private static void saveMetadata(List<CustomFont> fonts) throws IOException {
        Files.createDirectories(METADATA_PATH.getParent());
        JsonArray array = new JsonArray();
        for (CustomFont font : fonts) {
            JsonObject object = new JsonObject();
            object.addProperty("id", font.id());
            object.addProperty("name", font.name());
            object.addProperty("extension", font.extension());
            array.add(object);
        }
        try (Writer writer = Files.newBufferedWriter(METADATA_PATH, StandardCharsets.UTF_8)) {
            GSON.toJson(array, writer);
        }
    }

    private static void enablePack(Minecraft minecraft, boolean reload, Runnable afterReload) {
        try {
            PackRepository repository = minecraft.getResourcePackRepository();
            repository.reload();
            String packId = repository.getAvailableIds().stream()
                    .filter(id -> id.contains(PACK_FOLDER))
                    .findFirst().orElse(null);
            if (packId == null) {
                LOGGER.warn("Custom font resource pack was not discovered at {}", PACK_PATH);
                return;
            }
            boolean selectionChanged = false;
            if (!repository.getSelectedIds().contains(packId)) {
                repository.addPack(packId);
                minecraft.options.updateResourcePacks(repository);
                minecraft.options.save();
                selectionChanged = true;
            }
            if (reload && (selectionChanged || afterReload != null)) {
                minecraft.reloadResourcePacks().whenComplete((unused, error) -> minecraft.execute(() -> {
                    if (error != null) {
                        LOGGER.warn("Could not reload custom font resource pack", error);
                    } else if (afterReload != null) {
                        afterReload.run();
                    }
                }));
            } else if (afterReload != null) {
                afterReload.run();
            }
        } catch (Exception exception) {
            LOGGER.warn("Could not enable custom font resource pack", exception);
        }
    }

    public record CustomFont(String id, String name, String extension) {
    }
}

package dev.melix.damagenumbers.client.render;

import dev.melix.damagenumbers.client.config.DamageNumbersConfig.FontChoice;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;

public final class FontStyleResolver {
    private static final FontFactory FACTORY = createFactory();

    private FontStyleResolver() {
    }

    public static Component component(String text, FontChoice font, String customFontId) {
        MutableComponent component = Component.literal(text);
        String resourceId = font.resourceId(customFontId);
        Style style = component.getStyle();
        if (resourceId != null) {
            try {
                style = FACTORY.apply(style, resourceId);
            } catch (ReflectiveOperationException exception) {
                throw new IllegalStateException("Cannot apply font " + resourceId, exception);
            }
        }
        component.setStyle(style);
        return component;
    }

    private static FontFactory createFactory() {
        try {
            Class<?> resourceLocation = Class.forName("net.minecraft.resources.ResourceLocation");
            Method parse = resourceLocation.getMethod("tryParse", String.class);
            Method withFont = Style.class.getMethod("withFont", resourceLocation);
            return (style, id) -> (Style) withFont.invoke(style, parse.invoke(null, id));
        } catch (ClassNotFoundException ignored) {
            // Try the new API below.
        } catch (ReflectiveOperationException exception) {
            throw new IllegalStateException("Cannot initialize legacy font support", exception);
        }

        try {
            Class<?> identifier = Class.forName("net.minecraft.resources.Identifier");
            Method parse = identifier.getMethod("tryParse", String.class);
            Class<?> description = Class.forName("net.minecraft.network.chat.FontDescription");
            Class<?> resource = Class.forName("net.minecraft.network.chat.FontDescription$Resource");
            Constructor<?> constructor = resource.getConstructor(identifier);
            Method withFont = Style.class.getMethod("withFont", description);
            return (style, id) -> {
                Object fontId = constructor.newInstance(parse.invoke(null, id));
                return (Style) withFont.invoke(style, fontId);
            };
        } catch (ReflectiveOperationException exception) {
            throw new IllegalStateException("Cannot initialize font support", exception);
        }
    }

    @FunctionalInterface
    private interface FontFactory {
        Style apply(Style style, String id) throws ReflectiveOperationException;
    }
}

package dev.melix.damagenumbers.client.gui;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.Component;

final class FlatButton extends Button {
    private final boolean accent;
    private final boolean transparent;

    private FlatButton(int x, int y, int width, int height, Component message, OnPress onPress, boolean accent,
                       boolean transparent) {
        super(x, y, width, height, message, onPress, DEFAULT_NARRATION);
        this.accent = accent;
        this.transparent = transparent;
    }

    static Builder create(Component message, OnPress onPress) {
        return new Builder(message, onPress);
    }

    @Override
    protected void renderWidget(GuiGraphics graphics, int mouseX, int mouseY, float partialTick) {
        int background = transparent ? (isHoveredOrFocused() ? 0x332B313B : 0x00000000)
                : !active ? 0xFF14171C
                : accent ? (isHoveredOrFocused() ? 0xFF3D8BD0 : 0xFF2F76B7)
                : isHoveredOrFocused() ? 0xFF2B313B : 0xFF20252D;
        int text = active ? 0xFFF1F4F8 : 0xFF737B86;
        if (background != 0) {
            graphics.fill(getX(), getY(), getX() + getWidth(), getY() + getHeight(), background);
        }
        graphics.drawCenteredString(Minecraft.getInstance().font, getMessage(),
                getX() + getWidth() / 2, getY() + Math.max(1, (getHeight() - 8) / 2), text);
    }

    static final class Builder {
        private final Component message;
        private final OnPress onPress;
        private int x;
        private int y;
        private int width;
        private int height;
        private boolean accent;
        private boolean transparent;

        private Builder(Component message, OnPress onPress) {
            this.message = message;
            this.onPress = onPress;
        }

        Builder bounds(int x, int y, int width, int height) {
            this.x = x;
            this.y = y;
            this.width = width;
            this.height = height;
            return this;
        }

        Builder accent() {
            this.accent = true;
            return this;
        }

        Builder transparent() {
            this.transparent = true;
            return this;
        }

        FlatButton build() {
            return new FlatButton(x, y, width, height, message, onPress, accent, transparent);
        }
    }
}

package dev.melix.damagenumbers.client.gui;

import net.minecraft.client.gui.components.events.GuiEventListener;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

/**
 * Routes raw mouse input to the screen before the widget list sees it. The configuration screen
 * paints and hit-tests its own controls, so it needs the pointer events in a version independent
 * shape; every Minecraft flavour supplies its own subclass with the matching signatures.
 */
abstract class DamageNumbersScreenBase extends Screen {
    protected DamageNumbersScreenBase(Component title) {
        super(title);
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
        return handleMouseScroll(mouseX, mouseY, 0.0D, delta) || super.mouseScrolled(mouseX, mouseY, delta);
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        return handleMouseClick(mouseX, mouseY, button) || super.mouseClicked(mouseX, mouseY, button);
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        return handleMouseDrag(mouseX, mouseY, button)
                || super.mouseDragged(mouseX, mouseY, button, dragX, dragY);
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        return handleMouseRelease(mouseX, mouseY, button) || super.mouseReleased(mouseX, mouseY, button);
    }

    /** Drops keyboard focus so a click on a painted control closes any open text field. */
    protected final void clearScreenFocus() {
        setFocused((GuiEventListener) null);
    }

    protected abstract boolean handleMouseScroll(double mouseX, double mouseY, double horizontal, double vertical);

    protected abstract boolean handleMouseClick(double mouseX, double mouseY, int button);

    protected abstract boolean handleMouseDrag(double mouseX, double mouseY, int button);

    protected abstract boolean handleMouseRelease(double mouseX, double mouseY, int button);
}

